final class RobwOAuthDB {
 const NAME='robw_oauth_state_v1';
 static function read() { global $wpdb; $raw=$wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s",self::NAME)); if ($raw===null) return [null,['clients'=>[],'codes'=>[],'access'=>[],'refresh'=>[],'families'=>[],'tickets'=>[]]]; $v=json_decode($raw,true); if (!is_array($v)) throw new RuntimeException('Invalid OAuth state'); return [$raw,$v]; }
 static function mutate($fn) { global $wpdb; for($i=0;$i<24;$i++){[$old,$s]=self::read();foreach(['tickets','access','codes','refresh']as$kind){foreach($s[$kind]as$k=>$r){$end=!empty($r['used'])?($s['families'][$r['family']]['expires']??0):$r['expires'];if($end<time())unset($s[$kind][$k]);}}foreach($s['families']as$k=>$f)if($f['expires']<time())unset($s['families'][$k]);$result=$fn($s);$json=wp_json_encode($s);if(strlen($json)>8388608)throw new RuntimeException('OAuth capacity reached'); if($old===null){$ok=$wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$wpdb->options} (option_name,option_value,autoload) VALUES (%s,%s,'no')",self::NAME,$json));}else{$ok=$wpdb->query($wpdb->prepare("UPDATE {$wpdb->options} SET option_value=%s WHERE option_name=%s AND BINARY option_value=BINARY %s",$json,self::NAME,$old));}if($ok===false)throw new RuntimeException('OAuth persistence failed');if($ok===1||($json===$old&&$old!==null))return $result;usleep(random_int(500,3000));}throw new RuntimeException('OAuth state busy'); }
