final class RobwOAuthStore extends RobwOAuthVendor\OAuth2\Storage\Memory {
 public $family; public $pkce=[]; public $redirectOverride=[];
 function __construct(){parent::__construct();}
 function getClientDetails($id){[$raw,$s]=RobwOAuthDB::read();$c=$s['clients'][$id]??null;if(!$c)return null;return ['client_id'=>$id,'client_secret'=>'','redirect_uri'=>$this->redirectOverride[$id]??$c['redirect_uri'],'grant_types'=>'authorization_code refresh_token','scope'=>$c['scope']];}
 function checkClientCredentials($id,$secret=null){return $this->getClientDetails($id)!==null&&($secret===null||$secret==='');}
