 function setAuthorizationCode($code,$client,$user,$redirect,$expires,$scope=null,$id_token=null,$challenge=null,$method=null){if(!$challenge||$method!=='S256')throw new RuntimeException('PKCE required');$family=RobwOAuthDB::secret();RobwOAuthDB::mutate(function(&$s)use($code,$client,$user,$redirect,$expires,$scope,$challenge,$method,$family){$s['families'][$family]=['revoked'=>false,'expires'=>time()+86400,'user_id'=>$user,'client_id'=>$client,'scope'=>$scope];$s['codes'][RobwOAuthDB::key($code)]=['client_id'=>$client,'user_id'=>$user,'redirect_uri'=>$redirect,'expires'=>$expires,'scope'=>$scope,'code_challenge'=>$challenge,'code_challenge_method'=>$method,'family'=>$family,'used'=>false];});}
 private function record($kind,$secret){[$raw,$s]=RobwOAuthDB::read();$r=$s[$kind][RobwOAuthDB::key($secret)]??null;if(!$r)return null;if(!empty($r['used'])){RobwOAuthDB::revoke($r['family']);return null;}return RobwOAuthDB::active($s,$r)?$r:null;}
 function getAuthorizationCode($code){return $this->record('codes',$code);}
 function expireAuthorizationCode($code){return true;}
 function getAccessToken($token){return $this->record('access',$token);}
 function setAccessToken($token,$client,$user,$expires,$scope=null,$id_token=null){$this->put('access',$token,$client,$user,$expires,$scope);}
