}
final class RobwOAuthCode extends RobwOAuthVendor\OAuth2\GrantType\AuthorizationCode {
 function validateRequest(RobwOAuthVendor\OAuth2\RequestInterface $req,RobwOAuthVendor\OAuth2\ResponseInterface $res){$ok=parent::validateRequest($req,$res);if(!$ok){$e=$res->getParameter('error');if(in_array($e,['code_verifier_missing','code_verifier_invalid'],true))$res->setError(400,'invalid_request','Invalid PKCE verifier');elseif(in_array($e,['code_verifier_mismatch','redirect_uri_mismatch','code_challenge_method_invalid'],true))$res->setError(400,'invalid_grant','Invalid grant');return false;}if(!hash_equals($this->authCode['redirect_uri'],$req->request('redirect_uri'))){$res->setError(400,'invalid_grant','Invalid grant');return false;}return true;}
 function createAccessToken(RobwOAuthVendor\OAuth2\ResponseType\AccessTokenInterface $access,$client,$user,$scope){$this->storage->family=RobwOAuthDB::claim('codes',$this->authCode['code'],$client);return parent::createAccessToken($access,$client,$user,$scope);}
}
final class RobwOAuthRefresh extends RobwOAuthVendor\OAuth2\GrantType\RefreshToken {
 private $secret;private $db;
