}
final class RobwOAuthCodeResponse extends RobwOAuthVendor\OAuth2\ResponseType\AuthorizationCode { private $db; function __construct($db,$config){$this->db=$db;parent::__construct($db,$config);} function getAuthorizeResponse($params,$user_id=null){$params['code_challenge']=$this->db->pkce['challenge']??null;$params['code_challenge_method']='S256';return parent::getAuthorizeResponse($params,$user_id);} }
function robw_oauth_server($store){return new RobwOAuthVendor\OAuth2\Server(['access_token'=>$store,'client_credentials'=>$store,'authorization_code'=>$store,'refresh_token'=>$store,'scope'=>$store],['allow_public_clients'=>true,'allow_implicit'=>false,'enforce_state'=>true,'require_exact_redirect_uri'=>true,'access_lifetime'=>300,'refresh_token_lifetime'=>86400,'auth_code_lifetime'=>60],['authorization_code'=>new RobwOAuthCode($store),'refresh_token'=>new RobwOAuthRefresh($store)],['code'=>new RobwOAuthCodeResponse($store,['auth_code_lifetime'=>60])]);}
function robw_oauth_redirect_matches($registered,$requested){if(!is_string($requested)||preg_match('/[\x00-\x20\x7f]/',$requested))return false;$a=wp_parse_url($registered);$b=wp_parse_url($requested);if(!$a||!$b||isset($b['fragment'])||isset($b['user'])||isset($b['pass']))return false;if(($a['scheme']??'')==='http'&&in_array($a['host']??'',['127.0.0.1','[::1]'],true)){unset($a['port'],$b['port']);return $a===$b;}return hash_equals($registered,$requested);}
function robw_oauth_principal($authorization,$repo,$write=false){$token=null;if(preg_match('/^Bearer +([a-f0-9]{40,128})$/Di',$authorization,$m))$token=$m[1];elseif(preg_match('/^Basic +(\S+)$/Di',$authorization,$m)){$v=base64_decode($m[1],true);if($v!==false&&str_contains($v,':')){[$name,$value]=explode(':',$v,2);if($name==='oauth2'&&preg_match('/^[a-f0-9]{40,128}$/D',$value))$token=$value;}}if(!$token)return new WP_Error('invalid_token','Invalid credentials',['status'=>401]);$store=new RobwOAuthStore();$r=$store->getAccessToken($token);if(!$r||$r['expires']<=time())return new WP_Error('invalid_token','Invalid credentials',['status'=>401]);$scope=$write?'repo:write':'repo:read';if(!in_array($scope,explode(' ',$r['scope']),true)||!apply_filters('robw_oauth_repository_access',false,(int)$r['user_id'],$repo,$write))return new WP_Error('insufficient_scope','Repository access denied',['status'=>403]);return ['user_id'=>(int)$r['user_id'],'client_id'=>$r['client_id'],'scope'=>$r['scope']];}
